{"output":"// Форматтеры дат/статусов

// Нормализация входа даты: поддержка ISO-строк, чисел (секунды/миллисекунды), Date
const toDate = (input: string | number | Date): Date => {
  if (input instanceof Date) return input
  if (typeof input === 'number') {
    // Если похоже на секунды (10-значное), переводим в мс
    const ms = input < 1e12 ? input * 1000 : input
    return new Date(ms)
  }
  const s = String(input).trim()
  if (s === '') return new Date('')
  // Если строка — возможно число
  const asNum = Number(s)
  if (!Number.isNaN(asNum) && s.match(/^\d+$/)) {
    const ms = asNum < 1e12 ? asNum * 1000 : asNum
    return new Date(ms)
  }
  return new Date(s)
}

// Форматирование даты в локальный формат
export const formatDate = (value: string | number | Date): string => {
  try {
    const date = toDate(value)
    if (isNaN(date.getTime())) return 'Не указано'
    return date.toLocaleString('ru-RU', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      timeZone: 'Europe/Moscow'
    })
  } catch (error) {
    console.error('Error formatting date:', error, 'for value:', value)
    return String(value) || 'Ошибка даты'
  }
}

// Форматирование даты в относительный формат (например, "2 часа назад")
export const formatRelativeDate = (value: string | number | Date): string => {
  try {
    if (value === undefined || value === null || value === '') {
      return 'Неизвестно'
    }
    const date = toDate(value)
    // Проверяем что дата валидна
    if (isNaN(date.getTime())) {
      return 'Invalid Date'
    }

    const now = new Date()
    const diffMs = now.getTime() - date.getTime()
    const diffSecs = Math.floor(diffMs / 1000)
    const diffMins = Math.floor(diffSecs / 60)
    const diffHours = Math.floor(diffMins / 60)
    const diffDays = Math.floor(diffHours / 24)

    if (diffSecs < 60) {
      return `${diffSecs} сек. назад`
    } else if (diffMins < 60) {
      return `${diffMins} мин. назад`
    } else if (diffHours < 24) {
      return `${diffHours} ч. назад`
    } else if (diffDays < 30) {
      return `${diffDays} дн. назад`
    } else {
      return formatDate(date)
    }
  } catch (error) {
    console.error('Error formatting relative date:', error, 'for value:', value)
    return String(value) || 'Ошибка даты'
  }
}

// Форматирование статуса фичи
export const formatFeatureStatus = (status: string): string => {
  switch (status) {
    case 'NEW':
      return 'Новая'
    case 'PLANNED':
      return 'Запланирована'
    case 'RUNNING':
      return 'Выполняется'
    case 'DONE':
      return 'Завершена'
    case 'FAILED':
      return 'Ошибка'
    default:
      return status
  }
}

// Форматирование статуса задачи
export const formatTaskStatus = (status: string): string => {
  switch (status) {
    case 'NEW':
      return 'Новая'
    case 'RUNNING':
      return 'Выполняется'
    case 'DONE':
      return 'Завершена'
    case 'RETRYABLE_ERROR':
      return 'Ошибка (повтор)'
    case 'FAILED':
      return 'Ошибка'
    case 'WAIT_BUDGET':
      return 'Ждет бюджет'
    default:
      return status
  }
}

// Форматирование статуса запуска графа
export const formatGraphRunStatus = (status: string): string => {
  switch (status) {
    case 'RUNNING':
      return 'Выполняется'
    case 'DONE':
      return 'Завершен'
    case 'FAILED':
      return 'Ошибка'
    default:
      return status
  }
}

// Форматирование уровня лога
export const formatLogLevel = (level: string): string => {
  switch (level.toUpperCase()) {
    case 'DEBUG':
      return 'Отладка'
    case 'INFO':
      return 'Информация'
    case 'WARNING':
      return 'Предупреждение'
    case 'ERROR':
      return 'Ошибка'
    case 'CRITICAL':
      return 'Критично'
    default:
      return level
  }
}

// Форматирование роли
export const formatRole = (role: string): string => {
  switch (role) {
    case 'Architect':
      return 'Архитектор'
    case 'Dev':
      return 'Разработчик'
    case 'QA':
