              {uniqueStatuses.map(status => (
                <option key={status} value={status}>
                  {status === 'all' ? 'Все статусы' : status}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div>
          <div className="relative">
            <Filter className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
            <select
